<div class="d-flex flex-wrap gap-2 align-items-center mb-3"><h2 class="h5 mb-0"><?= e($a['title']) ?></h2><span class="text-muted"><?= e($a['ss']['subject_name'] . ' — ' . $a['ss']['grade_name'] . ' / ' . $a['ss']['section_name']) ?></span><span class="badge text-bg-warning" dir="ltr"><?= e($a['due_at']) ?></span><?= $a['max_score'] !== null ? '<span class="badge text-bg-secondary">من ' . (float)$a['max_score'] . '</span>' : '' ?>
  <span class="ms-auto d-flex gap-2"><a class="btn btn-outline-secondary" href="<?= url('school/lms?ss=' . (int)$a['section_subject_id']) ?>">رجوع</a><button class="btn btn-outline-danger" data-api="<?= url('api/v1/school/lms/assignments/' . (int)$a['id']) ?>" data-method="DELETE" data-confirm="حذف الواجب؟">حذف</button></span></div>
<?php if ($a['instructions']): ?><div class="card-s mb-3 math-content" style="white-space:pre-wrap"><?= e($a['instructions']) ?></div><?php endif; ?>
<div class="card-s"><div class="table-responsive"><table class="table align-middle"><thead><tr><th>الطالب</th><th>الحالة</th><th>الإجابة</th><th style="min-width:230px">الدرجة والملاحظة</th></tr></thead><tbody>
<?php foreach ($a['rows'] as $x): $sid = (int)$x['submission_id']; ?><tr><td><?= e($x['full_name']) ?></td><td><?php if (!$sid): ?><span class="badge text-bg-secondary">لم يسلّم</span><?php else: ?><span class="badge text-bg-<?= $x['graded_at'] ? 'success' : 'info' ?>"><?= $x['graded_at'] ? 'مُصحَّح' : 'سلّم' ?></span><?= $x['is_late'] ? ' <span class="badge text-bg-warning">متأخر</span>' : '' ?><br><small class="text-muted" dir="ltr"><?= e($x['submitted_at']) ?></small><?php endif; ?></td>
  <td style="max-width:300px"><?php if ($sid): ?><div class="small" style="white-space:pre-wrap"><?= e($x['body']) ?></div><?php if ($x['file_id']): ?><a href="<?= url('files/' . (int)$x['file_id']) ?>"><i class="bi bi-paperclip"></i> <?= e($x['original_name']) ?></a><?php endif; ?><?php endif; ?></td>
  <td><?php if ($sid): ?><form class="d-flex gap-1" method="post" action="<?= url("api/v1/school/lms/submissions/$sid/grade") ?>" data-ajax novalidate><?= csrf_field() ?><input class="form-control" style="max-width:80px" name="score" type="number" step="0.01" min="0" value="<?= $x['score'] === null ? '' : (float)$x['score'] ?>" placeholder="الدرجة" aria-label="الدرجة" required><input class="form-control" name="feedback" value="<?= e($x['feedback']) ?>" placeholder="ملاحظة" aria-label="ملاحظة"><button class="btn btn-primary" type="submit">حفظ</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></div>
